#!/usr/bin/env python3
"""theme-coverage.py — the theme pipeline's coverage record (PLAN 9.45, docs/themes/PIPELINE.md).

  theme-coverage.py [--root <tree>] [--import <walk>/coverage.json] [--check]

--import keeps a walk's result as docs/themes/coverage/<theme>.json (no screenshots: those stay with the walk). Every
run then writes docs/themes/coverage/<theme>.md (the gap list, the input to the mock-up stage) for each kept theme,
and docs/themes/coverage/README.md (the matrix: every bundled theme against every group of screens).
--check fails when a generated file differs from what it would write (CI keeps them in step).
"""
import argparse, json, os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
DIR = INV = None


def set_root(r):
    global ROOT, DIR, INV
    ROOT = os.path.abspath(r)
    DIR = os.path.join(ROOT, "docs", "themes", "coverage")
    INV = os.path.join(ROOT, "tests", "icefin", "web", "screens.json")
    if not os.path.exists(INV):  # a theme branch from before the pipeline: the inventory of this tree
        INV = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), "tests", "icefin", "web", "screens.json")
STATES = ["theme", "framed", "restyled", "stock", "missing", "dashboard", "skipped"]


def control():
    p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "theme-pipeline.json")
    return set(json.load(open(p)).get("control", [])) if os.path.exists(p) else set()


def themes():
    """The themes the pipeline refines: every bundled theme but the control ones."""
    return sorted(d for d in os.listdir(os.path.join(ROOT, "themes")) if os.path.isfile(os.path.join(ROOT, "themes", d, "theme.json")) and d not in control())


def groups():
    inv = json.load(open(INV))
    out = []
    for e in inv["screens"] + inv["dialogs"] + inv["player"]:
        if e["group"] not in out:
            out.append(e["group"])
    return out


def theme_md(cov):
    r, ents = cov["run"], cov["entries"]
    s = r.get("summary", {})
    lines = [f"# {r['theme']}: coverage", "",
             f"Generated by `scripts/icefin/theme-coverage.py` from the walk of {r.get('started', '?')} (theme {r.get('version', '?')}, "
             f"themes from {r.get('branch', '?') or '?'} {r.get('commit', '?') or '?'}, player {(r.get('player') or {}).get('version', '?')} "
             f"{(r.get('player') or {}).get('commit', '')}, on the workstation). Do not edit; walk again.", "",
             f"**{s.get('theme', 0)} of {s.get('entries', 0)}** drawn by the theme, **{s.get('gaps', 0)} gaps**, "
             f"{s.get('checksFailing', 0)} with failing checks, {s.get('skipped', 0)} skipped for want of lab data.", ""]
    if r.get("error"):
        lines += [f"> The walk stopped early: `{r['error']}`", ""]
    gaps = [e for e in ents if e["gap"]]
    if gaps:
        lines += ["## Gaps (what the mock-ups and the build cover)", "", "| Group | Screen | Now | Notes |", "|---|---|---|---|"]
        for e in gaps:
            note = e.get("note", "") or (", ".join(e.get("dialogs", [])) if e.get("dialogs") else "")
            lines.append(f"| {e['group']} | {e['name']} (`{e['id']}`) | {e['state']} | {note} |")
        lines.append("")
    bad = [e for e in ents if any(not c["ok"] for c in e.get("checks", []))]
    if bad:
        lines += ["## Failing checks", "", "| Screen | Check | Detail |", "|---|---|---|"]
        for e in bad:
            for c in e["checks"]:
                if not c["ok"]:
                    lines.append(f"| {e['name']} (`{e['id']}`) | {c['name']} | {c['detail'].replace('|', '/')[:160]} |")
        lines.append("")
    sk = [e for e in ents if e["state"] == "skipped"]
    if sk:
        lines += ["## Skipped (no lab data)", ""] + [f"- {e['name']} (`{e['id']}`): {e.get('note', '')}" for e in sk] + [""]
    lines += ["## Done", ""] + [f"- {e['name']} (`{e['id']}`)" for e in ents if not e["gap"] and e["state"] in ("theme", "dashboard")] + [""]
    return "\n".join(lines)


def matrix_md(covs):
    gs = groups()
    lines = ["# Theme coverage", "",
             "Generated by `scripts/icefin/theme-coverage.py` from each theme's last walk (`docs/themes/PIPELINE.md`). "
             "A cell is screens drawn by the theme over screens walked in that group; ✓ when none is left to jellyfin-web. "
             "The server dashboard counts when it stays stock. Control themes (" + ", ".join(sorted(control())) + ") stay stock on purpose and are not walked. Do not edit; walk again.", "",
             "| Theme | Walked | " + " | ".join(gs) + " | Gaps |", "|---|---|" + "---|" * len(gs) + "---|"]
    for t in themes():
        c = covs.get(t)
        if not c:
            lines.append(f"| {t} | not yet | " + " | ".join("" for _ in gs) + " | |")
            continue
        cells = []
        for g in gs:
            es = [e for e in c["entries"] if e["group"] == g and e["state"] != "skipped"]
            ok = sum(not e["gap"] for e in es)
            cells.append("" if not es else "✓" if ok == len(es) else f"{ok}/{len(es)}")
        r = c["run"]
        lines.append(f"| [{t}]({t}.md) | {r.get('started', '')[:10]} {r.get('version', '')} | " + " | ".join(cells) + f" | {r.get('summary', {}).get('gaps', '')} |")
    lines.append("")
    return "\n".join(lines)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--import", dest="imp")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--root", default=ROOT, help="the tree whose docs/themes/coverage/ to write (a theme's worktree)")
    a = ap.parse_args()
    set_root(a.root)
    os.makedirs(DIR, exist_ok=True)
    if a.imp:
        cov = json.load(open(a.imp))
        cov["run"].pop("app", None)
        cov["run"].pop("themePath", None)
        json.dump(cov, open(os.path.join(DIR, cov["run"]["theme"] + ".json"), "w"), indent=1)
        open(os.path.join(DIR, cov["run"]["theme"] + ".json"), "a").write("\n")
    covs = {}
    for t in themes():
        p = os.path.join(DIR, t + ".json")
        if os.path.exists(p):
            covs[t] = json.load(open(p))
    want = {os.path.join(DIR, "README.md"): matrix_md(covs)}
    for t, c in covs.items():
        want[os.path.join(DIR, t + ".md")] = theme_md(c)
    stale = []
    for p, text in want.items():
        old = open(p).read() if os.path.exists(p) else None
        if old != text:
            if a.check:
                stale.append(os.path.relpath(p, ROOT))
            else:
                open(p, "w").write(text)
    if stale:
        print("theme-coverage: out of date (run scripts/icefin/theme-coverage.py): " + ", ".join(stale))
        return 1
    print(f"theme-coverage: {len(covs)} themes walked of {len(themes())}" + ("" if a.check else f" -> {os.path.relpath(DIR, ROOT)}"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
